interface-vs-type.example:
// Interfaces for extendable shapes
interface Repository<T> {
  findById(id: string): Promise<T | null>;
  save(entity: T): Promise<T>;
}

interface UserRepository extends Repository<User> {
  findByEmail(email: string): Promise<User | null>;
}

// Type aliases for unions and mapped types
type UserId = string;
type Result<T> = { ok: true; value: T } | { ok: false; error: Error };
type PartialUser = Partial<User>;

// Nullability at the use site, not inside the alias
type ApiKey = string;               // not: type ApiKey = string | null
function findKey(id: string): ApiKey | null { ... }

enums.example:
// Preferred: as const object with derived type
const Direction = {
  North: "north",
  South: "south",
  East: "east",
  West: "west",
} as const;
type Direction = (typeof Direction)[keyof typeof Direction];
// Direction is "north" | "south" | "east" | "west" at runtime — no magic

// Acceptable when interop requires it: string enum
enum HttpMethod {
  Get = "GET",
  Post = "POST",
}

// Avoid: numeric enum has reverse mapping (Direction[0] === "North")
enum Direction { North, South, East, West }

generics.example:
// Constrained generic: safe property access
function sortBy<T extends { id: number }>(items: T[]): T[] {
  return [...items].sort((a, b) => a.id - b.id);
}

// Unconstrained with unknown: force callers to narrow
function parseJson(input: string): unknown {
  return JSON.parse(input);  // caller must narrow before use
}

// WRONG: any constraint defeats type safety
function identity<T extends any>(x: T): T { return x; }
// RIGHT:
function identity<T>(x: T): T { return x; }

readonly.example:
interface Config {
  readonly apiUrl: string;
  readonly maxRetries: number;
  readonly allowedMethods: ReadonlyArray<string>;
}

function processItems(items: readonly string[]): string[] {
  // items.push("x")  // Error: cannot mutate a readonly array
  return items.map(i => i.toUpperCase());  // map returns a new array
}

type-assertions.example:
// WRONG: assertion silences the compiler without proving anything
const user = getUser() as User;
const el = document.getElementById("root") as HTMLDivElement;

// RIGHT: type guard narrows safely
function isUser(value: unknown): value is User {
  return (
    typeof value === "object" &&
    value !== null &&
    "id" in value &&
    typeof (value as { id: unknown }).id === "string"
  );
}

// RIGHT: null check instead of !
const el = document.getElementById("root");
if (el === null) throw new Error("Root element not found");
el.textContent = "Hello";  // el is HTMLElement here

boxed-types.example:
// WRONG: boxed types
function greet(name: String): String { return "Hello, " + name; }

// RIGHT: primitive types
function greet(name: string): string { return `Hello, ${name}`; }

overloads.example:
// WRONG: separate overloads for trailing optional params
interface Example {
  diff(one: string): number;
  diff(one: string, two: string): number;
  diff(one: string, two: string, three: boolean): number;
}

// RIGHT: optional parameters
interface Example {
  diff(one: string, two?: string, three?: boolean): number;
}

// WRONG: overloads for union types
interface Moment {
  utcOffset(b: number): Moment;
  utcOffset(b: string): Moment;
}

// RIGHT: union type
interface Moment {
  utcOffset(b: number | string): Moment;
}

// When order matters: specific overloads before general
declare function fn(x: HTMLDivElement): string;  // specific first
declare function fn(x: HTMLElement): number;
declare function fn(x: unknown): unknown;         // general last

callbacks.example:
// WRONG: any allows return value to be accidentally used
function forEach(items: string[], callback: (item: string) => any): void { }

// RIGHT: void prevents return value misuse
function forEach(items: string[], callback: (item: string) => void): void { }

// WRONG: optional parameter implies caller may pass undefined
interface Fetcher {
  getObject(done: (data: unknown, elapsedTime?: number) => void): void;
}

// RIGHT: required parameter (caller may still ignore it in their function)
interface Fetcher {
  getObject(done: (data: unknown, elapsedTime: number) => void): void;
}

module-rules.example:
// WRONG: namespace
namespace Utils {
  export function format(s: string): string { return s.trim(); }
}

// RIGHT: ES module named export
export function format(s: string): string { return s.trim(); }

// WRONG: default export
export default class UserService { }

// RIGHT: named export
export class UserService { }

// Type-only import
import type { User, UserDTO } from './types';
import { UserService } from './user-service';  // value import

// WRONG: mutable exported binding
export let currentUser: User | null = null;

// RIGHT: export getter
let _currentUser: User | null = null;
export function getCurrentUser(): User | null { return _currentUser; }

class-rules.example:
// Parameter properties + readonly: no boilerplate
class OrderService {
  constructor(
    private readonly repository: OrderRepository,
    private readonly logger: Logger,
  ) {}

  async getOrder(id: string): Promise<Order | null> {
    this.logger.info('Fetching order', { id });
    return this.repository.findById(id);
  }
}

// WRONG: container class with static methods
class StringUtils {
  static capitalize(s: string): string { return s[0].toUpperCase() + s.slice(1); }
}

// RIGHT: module-level export
export function capitalize(s: string): string { return s[0].toUpperCase() + s.slice(1); }
